     4	function reservedSeats(session: SessionState): number {
     5	  return session.enrollments.filter(entry => entry.status !== 'waitlisted').length;
     6	}
     7	
     8	function fillAvailableSeats(session: SessionState): void {
     9	  if (!session.admissionsOpen) return;
    10	  let available = session.capacity - reservedSeats(session);
    11	  for (const entry of session.enrollments) {
    12	    if (available === 0) break;
    13	    if (entry.status === 'waitlisted') {
    14	      entry.status = 'offered';
    15	      available--;
    16	    }
    17	  }
    18	}
    19	
    20	function offeredEnrollment(session: SessionState, rawEmail: string): Enrollment {
    21	  const email = canonicalEmail(rawEmail);
    22	  const entry = session.enrollments.find(entry => entry.email === email);
    23	  if (!entry) throw new DeskError('NOT_ENROLLED', 'Employee is not enrolled');
    24	  if (entry.status !== 'offered') throw new DeskError('NOT_OFFERED', 'Employee has no seat offer');
    25	  return entry;
    26	}
    27	
    28	export class TrainingDesk {
    29	  private readonly store: SessionStore;
    30	
    31	  constructor(seeds: readonly SessionSeed[]) {
    32	    this.store = new SessionStore(seeds);
    33	  }
    34	
    35	  enroll(sessionId: string, rawEmail: string, options?: { waitlist: boolean }): Enrollment {
    36	    const session = this.store.get(sessionId);
    37	    if (!session.admissionsOpen) {
    38	      throw new DeskError('ADMISSIONS_CLOSED', 'Session admissions are closed');
    39	    }
    40	    const email = canonicalEmail(rawEmail);
    41	    if (session.enrollments.some(entry => entry.email === email)) {
    42	      throw new DeskError('ALREADY_ENROLLED', 'Employee already enrolled');
    43	    }
    44	    const full = reservedSeats(session) >= session.capacity;
    45	    if (full && !options?.waitlist) {
    46	      throw new DeskError('FULL', 'Session is full');
    47	    }
    48	    const entry: Enrollment = { email, status: full ? 'waitlisted' : 'confirmed' };
    49	    session.enrollments.push(entry);
    50	    return { ...entry };
    51	  }
    52	
    53	  cancel(sessionId: string, rawEmail: string): void {
    54	    const session = this.store.get(sessionId);
    55	    const email = canonicalEmail(rawEmail);
    56	    const index = session.enrollments.findIndex(entry => entry.email === email);
    57	    if (index < 0) throw new DeskError('NOT_ENROLLED', 'Employee is not enrolled');
    58	    session.enrollments.splice(index, 1);
    59	    fillAvailableSeats(session);
    60	  }
    61	
    62	  acceptOffer(sessionId: string, rawEmail: string): Enrollment {
    63	    const session = this.store.get(sessionId);
    64	    const entry = offeredEnrollment(session, rawEmail);
    65	    entry.status = 'confirmed';
    66	    return { ...entry };
    67	  }
    68	
    69	  declineOffer(sessionId: string, rawEmail: string): void {
    70	    const session = this.store.get(sessionId);
    71	    const entry = offeredEnrollment(session, rawEmail);
    72	    session.enrollments.splice(session.enrollments.indexOf(entry), 1);
    73	    fillAvailableSeats(session);
    74	  }
    75	
    76	  setAdmissions(sessionId: string, open: boolean): void {
    77	    const session = this.store.get(sessionId);
    78	    session.admissionsOpen = open;
    79	    fillAvailableSeats(session);
    80	  }
    81	
    82	  roster(sessionId: string): Roster {
    83	    const session = this.store.get(sessionId);
    84	    return {
    85	      id: session.id,
    86	      title: session.title,
    87	      capacity: session.capacity,
    88	      admissionsOpen: session.admissionsOpen,
    89	      enrollments: session.enrollments.map(entry => ({ ...entry })),
    90	    };
    91	  }
    92	}
